final class ValidateMissionHandler
{
    public function __construct(
        private MissionRepository $missions,
        private MFilesClient $ged,
    ) {}

    public function __invoke(ValidateMission $cmd): void
    {
        $mission = $this->missions->get($cmd->missionId);
        $mission->validate($cmd->reviewer);
        $this->ged->archive($mission->documents());
    }
}

export function useProgress(courseId: string) {
  const { data } = useFetch<Progress>(`/api/courses/${courseId}/progress`)

  const percent = computed(() =>
    data.value ? Math.round(data.value.done / data.value.total * 100) : 0
  )

  return { percent, lessons: computed(() => data.value?.lessons ?? []) }
}

