router.post('/processes/:id/submissions', async (req, res) => {
  const process = await Process.findById(req.params.id)
  const errors = process.schema.validate(req.body)
  if (errors.length) return res.status(422).json({ errors })

  const submission = await Submission.create({ process, data: req.body })
  res.status(201).json(submission)
})
